/**
 * n8n Code node — Google SERP parser (ScrapeUnblocker output)
 * ------------------------------------------------------------
 * MODE:      "Run Once for All Items"
 * LANGUAGE:  JavaScript
 * DEPS:      none (works in the default n8n sandbox — no cheerio needed)
 *
 * INPUT:     the raw HTTP Request [ScrapeUnblocker] output. Handles the body
 *            arriving as a string, as ["<html>..."], or nested in a field
 *            (data / body / html / content / response).
 * OUTPUT:    one item per organic result, ready for Google Sheets "Append":
 *            keyword | rank | title | url | metaDescription | publishedDate | date
 *
 * NOTE:      Only classic organic results are returned. Ads, "People also ask",
 *            video/image packs, and knowledge panels are intentionally skipped.
 */

// ---------- helpers ----------
function decodeEntities(str) {
  return str
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&hellip;/g, '\u2026');
}

function stripTags(html) {
  return decodeEntities(html.replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

// Pull the HTML string out of whatever shape the item arrives in.
function getHtml(json) {
  if (typeof json === 'string') return json;
  if (Array.isArray(json)) return json.find(v => typeof v === 'string' && v.includes('<')) || '';
  const keys = ['data', 'body', 'html', 'content', 'result', 'response', 'page'];
  for (const k of keys) {
    const v = json && json[k];
    if (typeof v === 'string' && v.includes('<html')) return v;
    if (Array.isArray(v)) {
      const s = v.find(x => typeof x === 'string' && x.includes('<'));
      if (s) return s;
    }
  }
  for (const v of Object.values(json || {})) {
    if (typeof v === 'string' && v.includes('<html')) return v;
  }
  return '';
}

// Find the keyword. Order: passthrough field → ?q= from a REAL url field → <title> tag.
// NOTE: never scan the page HTML for q= — Google's inline scripts contain q= too.
function getKeyword(json, html) {
  // 1. Explicit passthrough field (cleanest — see setup note).
  if (json && typeof json.keyword === 'string' && json.keyword.trim()) return json.keyword.trim();
  // 2. A genuine URL field only — parse its ?q= param.
  const urlField = json && (json.url || json.query || json.q);
  if (typeof urlField === 'string' && /^https?:\/\//.test(urlField)) {
    const m = urlField.match(/[?&]q=([^&]+)/);
    if (m) { try { return decodeURIComponent(m[1].replace(/\+/g, ' ')).trim(); } catch { return m[1].trim(); } }
  }
  // 3. Fallback: the page <title> ("<kw> - Google Suche/Search").
  const t = html.match(/<title>\s*([\s\S]*?)\s*-\s*Google\b/i);
  if (t) return t[1].replace(/\s+/g, ' ').trim();
  return 'unknown';
}

// ---------- main ----------
const out = [];
const scrapedIso = new Date().toISOString();
const scrapedDate = scrapedIso.slice(0, 10); // YYYY-MM-DD

for (const item of $input.all()) {
  const json = item.json;
  const html = getHtml(json);
  if (!html) continue;

  const keyword = getKeyword(json, html);

  // Primary: current organic anchor class. Fallback: any http(s) link wrapping an <h3>.
  let linkRe = /<a class="zReHs"[^>]*href="([^"]+)"[^>]*>\s*<h3[^>]*>([\s\S]*?)<\/h3>/g;
  let matches = [...html.matchAll(linkRe)];
  if (matches.length === 0) {
    linkRe = /<a[^>]*href="(https?:\/\/[^"]+)"[^>]*>\s*<h3[^>]*>([\s\S]*?)<\/h3>/g;
    matches = [...html.matchAll(linkRe)];
  }

  matches.forEach((m, i) => {
    const url = decodeEntities(m[1]);
    const title = stripTags(m[2]);

    // Snippet: first VwiC3b block between this result and the next.
    const start = m.index;
    const end = i + 1 < matches.length ? matches[i + 1].index : html.length;
    const slice = html.slice(start, end);
    const snipM = slice.match(/<div[^>]*class="[^"]*VwiC3b[^"]*"[^>]*>([\s\S]*?)<\/div>/);
    let snippet = snipM ? stripTags(snipM[1]) : '';

    // Strip a leading date Google sometimes prefixes (e.g. "25.12.2019 — ...").
    let publishedDate = '';
    const d = snippet.match(/^(\d{1,2}\.\d{1,2}\.\d{4})\s*[\u2014\-]?\s*/);
    if (d) { publishedDate = d[1]; snippet = snippet.slice(d[0].length).trim(); }

    out.push({
      json: {
        keyword,
        rank: i + 1,
        title,
        url,
        metaDescription: snippet,
        publishedDate,      // '' when Google didn't show one
        date: scrapedDate,  // date scraped, YYYY-MM-DD
      },
    });
  });
}

return out;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();
